"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[305],{49352:e=>{e.exports=JSON.parse('{"functions":[{"name":"Register","desc":"Register a force-save callback. Call once per persistence manager.","params":[{"name":"flush","desc":"","lua_type":"() -> ()"}],"returns":[],"function_type":"static","source":{"line":32,"path":"src/ServerStorage/SharedModules/PersistenceRegistry.luau"}},{"name":"RegisterHandoff","desc":"Register a teleport hand-off pair. Call once per persistence manager.","params":[{"name":"release","desc":"","lua_type":"(Player) -> ()"},{"name":"reopen","desc":"","lua_type":"(Player) -> ()"}],"returns":[],"function_type":"static","source":{"line":42,"path":"src/ServerStorage/SharedModules/PersistenceRegistry.luau"}},{"name":"ReleaseForTeleport","desc":"Save and end every registered session of `players` before a teleport. Call\\n`Reopen` for them if the teleport fails.","params":[{"name":"players","desc":"","lua_type":"{ Player }"}],"returns":[],"function_type":"static","source":{"line":51,"path":"src/ServerStorage/SharedModules/PersistenceRegistry.luau"}},{"name":"Reopen","desc":"Start again every session `ReleaseForTeleport` ended for `players`. A no-op for\\na player who was not released or has left.","params":[{"name":"players","desc":"","lua_type":"{ Player }"}],"returns":[],"function_type":"static","source":{"line":65,"path":"src/ServerStorage/SharedModules/PersistenceRegistry.luau"}},{"name":"FlushAll","desc":"Run every registered flush in parallel and wait for all to finish or until\\n`timeoutSeconds` elapses. Returns true if all finished in time.","params":[{"name":"timeoutSeconds","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"static","source":{"line":78,"path":"src/ServerStorage/SharedModules/PersistenceRegistry.luau"}}],"properties":[],"types":[],"name":"PersistenceRegistry","desc":"Central point for force-saving every persisted player profile before the\\nserver drains players (see DisruptionCoordinator). Each persistence manager\\n(CoinManager, PerkManager, ArmorManager, SettingsManager, XPManager) calls\\n`Register` once from its `Initialize()` with a callback that iterates its\\nown active profiles and calls `profile:Save()`.\\n\\n`Save()` \u2014 not `EndSession()` \u2014 is used so players stay connected until the\\nteleport; `EndSession` (which some managers wire to a kick) still runs\\nnaturally on PlayerRemoving. ProfileStore session-locking is the correctness\\nbackstop even if a save is still in flight when a player reaches the lobby.\\n\\nTeleport hand-off: each manager also calls `RegisterHandoff` with a `release`\\n(save and end one player\'s session WITHOUT a kick, so the next place opens it\\nwithout waiting on the session lock) and a `reopen` (start it again after a\\nfailed teleport). The Lobby calls `ReleaseForTeleport` right before a party\\nteleport and `Reopen` if it fails.","realm":["Server"],"source":{"line":23,"path":"src/ServerStorage/SharedModules/PersistenceRegistry.luau"}}')}}]);